def _logpolar_masks(size, nr, ns):
    """Cortical-magnification pooling regions: LOG-spaced eccentricity rings x angular sectors, so the
    fovea (small eccentricity) gets finer sampling than the periphery -- matching V1 retinotopy.
    Returns (nr*ns, size, size) soft (area-normalized) region masks."""
    y, x = torch.meshgrid(torch.arange(size).float(), torch.arange(size).float(), indexing="ij")
    c = (size - 1) / 2.0
    dy, dx = y - c, x - c
    r = torch.sqrt(dx ** 2 + dy ** 2)
    r = r / (r.max() + 1e-8)
    theta = torch.atan2(dy, dx)
    r_edges = torch.logspace(math.log10(0.04), math.log10(1.0), nr + 1)
    r_edges[0] = 0.0
    a_edges = torch.linspace(-math.pi, math.pi, ns + 1)
    masks = []
    for i in range(nr):
        rm = (r >= r_edges[i]) & ((r <= r_edges[i + 1]) if i == nr - 1 else (r < r_edges[i + 1]))
        for j in range(ns):
            am = (theta >= a_edges[j]) & ((theta <= a_edges[j + 1]) if j == ns - 1 else (theta < a_edges[j + 1]))
            masks.append((rm & am).float())
    m = torch.stack(masks)
    return m / (m.sum(dim=(1, 2), keepdim=True) + 1e-8)


def _hann2d(size):
    w = torch.hann_window(size, periodic=False)
    return (w[:, None] * w[None, :])


def _spectral_masks(size, nr, ns, radial_only=False):
    """One-hot (normalized) bin masks over the fftshifted amplitude spectrum of a size x size image.
    Bins are log-spaced radial (spatial-frequency) rings crossed with orientation sectors (mod pi,
    since a real image's spectrum is centrosymmetric). Returns (nbins, size, size)."""
    f = torch.fft.fftshift(torch.fft.fftfreq(size))
    fy, fx = torch.meshgrid(f, f, indexing="ij")
    r = torch.sqrt(fx ** 2 + fy ** 2)
    theta = torch.atan2(fy, fx) % math.pi
    rmax = float(r.max())
    rmin = float(f[f > 0].min())
    r_edges = torch.logspace(math.log10(rmin), math.log10(rmax + 1e-6), nr + 1)
    a_edges = torch.linspace(0, math.pi, ns + 1)
    masks = []
    for i in range(nr):
        rmask = (r >= r_edges[i]) & ((r <= r_edges[i + 1]) if i == nr - 1 else (r < r_edges[i + 1]))
        if radial_only:
            masks.append(rmask.float())
            continue
        for j in range(ns):
            amask = (theta >= a_edges[j]) & ((theta <= a_edges[j + 1]) if j == ns - 1 else (theta < a_edges[j + 1]))
            masks.append((rmask & amask).float())
    m = torch.stack(masks)
    return m / (m.sum(dim=(1, 2), keepdim=True) + 1e-8)


def _gabor_bank(n_orient, ksize, lam, sigma, gamma=GAMMA):
    half = (ksize - 1) / 2.0
    ys, xs = torch.meshgrid(
        torch.arange(ksize) - half, torch.arange(ksize) - half, indexing="ij")
    kernels = []
    for phase in (0.0, math.pi / 2.0):
        for k in range(n_orient):
            theta = math.pi * k / n_orient
            xr = xs * math.cos(theta) + ys * math.sin(theta)
            yr = -xs * math.sin(theta) + ys * math.cos(theta)
            env = torch.exp(-(xr ** 2 + (gamma ** 2) * yr ** 2) / (2 * sigma ** 2))
            carrier = torch.cos(2 * math.pi * xr / lam + phase)
            g = env * carrier
            g = g - g.mean()
            g = g / (g.norm() + 1e-8)
            kernels.append(g)
    return torch.stack(kernels).unsqueeze(1)     # (n_orient*2, 1, k, k)


def _s2_bank():
    """Depthwise second-order bank: (N_ORIENT*N_ORIENT2*2, 1, K2, K2), each of the N_ORIENT input
    energy channels gets its own N_ORIENT2 quadrature pair (groups=N_ORIENT)."""
    single = _gabor_bank(N_ORIENT2, KSIZE2, LAMBDA2, SIGMA2)   # (N_ORIENT2*2,1,k,k)
    even = single[:N_ORIENT2]; odd = single[N_ORIENT2:]
    per = torch.cat([even, odd], dim=0)                        # (N_ORIENT2*2,1,k,k)
    return per.repeat(N_ORIENT, 1, 1, 1)                       # (N_ORIENT*N_ORIENT2*2,1,k,k)


def _dog_kernel():
    half = (DOG_K - 1) / 2.0
    ys, xs = torch.meshgrid(
        torch.arange(DOG_K) - half, torch.arange(DOG_K) - half, indexing="ij")
    r2 = xs ** 2 + ys ** 2
    g1 = torch.exp(-r2 / (2 * DOG_S1 ** 2)); g1 = g1 / g1.sum()
    g2 = torch.exp(-r2 / (2 * DOG_S2 ** 2)); g2 = g2 / g2.sum()
    return (g1 - g2).reshape(1, 1, DOG_K, DOG_K)


def _logpolar_warp_grid(size=96, r_min=0.03, r_max=1.0):
    """Sampling grid (1, size, size, 2) that resamples an image into LOG-POLAR coordinates: output row =
    log-spaced eccentricity ring, output col = angle. Feeds grid_sample so a Cartesian Gabor bank run on
    the warped image detects concentric/radial/spiral (radial-frequency) structure around fixation."""
    i = torch.arange(size).float()
    r = r_min * (r_max / r_min) ** (i / (size - 1))
    theta = 2 * math.pi * torch.arange(size).float() / size
    rr = r[:, None]
    tt = theta[None, :]
    x = rr * torch.cos(tt)
    y = rr * torch.sin(tt)
    return torch.stack([x, y], dim=-1).unsqueeze(0)


def _mag(cur, gb):
    resp = F.conv2d(cur, gb, padding=gb.shape[-1] // 2)
    even = resp[:, :N_ORIENT]; odd = resp[:, N_ORIENT:]
    return torch.sqrt(even ** 2 + odd ** 2 + 1e-8)


class Model:
    name = "opponent-gabor-scatter-fovea-globalfourier"
    idea = "sharper hue bins (higher von-Mises concentration) for more distinct colour categories in the balanced space"
    description = (
        "The perceptual + compressive colour-composition champion with the HUE soft-bin concentration raised "
        "(von-Mises kappa 3.0 -> 4.5) in both the marginal hue histograms and the joint hue x lightness "
        "identity histogram: sharper, more distinct colour-category bins, now that the perceptually-balanced "
        "opponent space spreads colours evenly around the hue circle. Never trained.")
    insight = (
        "Perceptual balancing + compressive magnitude binning took ventral to 0.4314. With the hue circle now "
        "balanced, the soft hue bins can be sharpened without starving the sparse blue-yellow side, making "
        "colour categories (green/blue/warm) more distinct for material identity. A net-zero knob tune. If "
        "PPA/ventral rise, sharper colour categories help; if flat/worse, kappa 3.0 was near-optimal and I "
        "restore it.")

    def __init__(self):
        self._gb = None
        self._gb2 = None
        self._rf = None
        self._s2 = None
        self._dog = None
        self._iu = torch.triu_indices(N_ORIENT, N_ORIENT, offset=1)
        self._lp = _logpolar_masks(LP_SIZE, LP_RINGS, LP_SECTORS)
        self._lpwarp = _logpolar_warp_grid(96)
        self._fmask = _spectral_masks(FFT_SIZE, FFT_RINGS, FFT_SECTORS)
        self._fmask_c = _spectral_masks(FFT_SIZE, FFT_CHROMA_RINGS, 1, radial_only=True)
        self._fmask_w = _spectral_masks(FFT_WIN_SIZE, FFT_WIN_RINGS, FFT_WIN_SECTORS)
        self._win = _hann2d(FFT_SIZE)
        self._win_w = _hann2d(FFT_WIN_SIZE)
        self._sobel_x = torch.tensor([[-1., 0., 1.], [-2., 0., 2.], [-1., 0., 1.]]).reshape(1, 1, 3, 3) / 4.0
        self._sobel_y = self._sobel_x.transpose(-1, -2).clone()
        self.n_params = int(N_ORIENT * 2 * KSIZE * KSIZE + N_ORIENT * 2 * KSIZE_B * KSIZE_B
                            + N_ORIENT2 * 2 * KSIZE2 * KSIZE2 + DOG_K * DOG_K
                            + sum(N_ORIENT * 2 * k * k for (_l, _s, k) in LUM_WLS)
                            + RF_CH * N_ORIENT * RF_K * RF_K + RF_CH * RF_CH * RF_K * RF_K)

    def _to_images(self, X):
        X = torch.as_tensor(X).float()
        N = X.shape[0]
        return X.reshape(N, SIDE, SIDE, 3).permute(0, 3, 1, 2)

    def _texture_stats(self, energy):
        """Compact texture descriptor: per-region std of each orientation channel + pairwise cross-
        orientation correlations, on a coarse TEX_GRID grid (per-image spatial statistics)."""
        N, C, h, w = energy.shape
        G = TEX_GRID
        m = F.adaptive_avg_pool2d(energy, (G, G))
        ee = torch.einsum('nchw,ndhw->ncdhw', energy, energy).reshape(N, C * C, h, w)
        p = F.adaptive_avg_pool2d(ee, (G, G)).reshape(N, C, C, G, G)
        cov = p - m.unsqueeze(2) * m.unsqueeze(1)
        var = torch.diagonal(cov, dim1=1, dim2=2).permute(0, 3, 1, 2)
        std = torch.sqrt(var.clamp_min(0) + 1e-6)
        ii, jj = self._iu[0], self._iu[1]
        corr = (cov[:, ii, jj] / (std[:, ii] * std[:, jj] + 1e-6)).clamp(-1, 1)
        return torch.cat([std, corr], dim=1).reshape(N, -1)

    def _second_order(self, energy):
        """energy (N,N_ORIENT,h,w) -> depthwise 2nd Gabor -> quadrature energy (N,N_ORIENT*N_ORIENT2,h,w).
        Optionally cross-orientation divisively-normalized (mid-level contrast-gain-control on the
        scattering output) before the log compression."""
        resp = F.conv2d(energy, self._s2, padding=KSIZE2 // 2, groups=N_ORIENT)
        resp = resp.reshape(resp.shape[0], N_ORIENT, 2, N_ORIENT2, resp.shape[-2], resp.shape[-1])
        even = resp[:, :, 0]; odd = resp[:, :, 1]
        e = torch.sqrt(even ** 2 + odd ** 2 + 1e-8)
        e = e.reshape(e.shape[0], N_ORIENT * N_ORIENT2, e.shape[-2], e.shape[-1])
        if S2_OUTPUT_DN:
            p = F.avg_pool2d((e ** 2).sum(1, keepdim=True), 3, stride=1, padding=1)
            s2 = DN_SIG * (e ** 2).mean(dim=(1, 2, 3), keepdim=True) + 1e-6
            e = e / torch.sqrt(s2 + p)
        e = torch.log1p(10.0 * e)
        return e

    def _symmetry(self, e, grid, axis=3):
        """MIRROR-SYMMETRY descriptor. Mirror the oriented-energy stack across the vertical (axis=3, left-
        right) or horizontal (axis=2, up-down) axis -- flip spatially AND permute the orientation channels
        (both reflections map orientation theta -> pi-theta, index k -> (N_ORIENT-k)%N_ORIENT) so the
        mirror is a true reflection of oriented structure -- then take the per-orientation local
        correlation between the energy and its mirror on a grid. High where structure is mirror-symmetric
        (faces/centered objects for left-right; reflections/layout for up-down) -- a mid/high-level
        configural cue absent from every local energy statistic in the model."""
        perm = [(-k) % N_ORIENT for k in range(N_ORIENT)]
        e_mir = torch.flip(e, dims=[axis])[:, perm]
        return self._local_corr(e, e_mir, G=grid)

    def _phase_congruency(self, chan, banks, grid=3):
        """CONTRAST-INVARIANT phase congruency (Kovesi). Structural features -- edges and lines -- occur
        where the even (cos) and odd (sin) quadrature-Gabor responses are IN PHASE across SCALES. Summing
        the complex responses across scales and dividing by the summed amplitude gives, per orientation,
        PC = |sum_s (even_s + i odd_s)| / (sum_s |.|_s + eps) in [0,1] -- high at true structural feature
        points independent of contrast, and provably ORTHOGONAL to raw oriented ENERGY (which the whole
        model already encodes). Pooled on a grid; targets contour/feature-point structure in ventral."""
        SE = SO = SA = 0.0
        for gb in banks:
            resp = F.conv2d(chan, gb, padding=gb.shape[-1] // 2)
            even = resp[:, :N_ORIENT]; odd = resp[:, N_ORIENT:]
            SE = SE + even; SO = SO + odd
            SA = SA + torch.sqrt(even ** 2 + odd ** 2 + 1e-8)
        pc = torch.sqrt(SE ** 2 + SO ** 2 + 1e-8) / (SA + 1e-6)
        return F.adaptive_avg_pool2d(pc, (grid, grid)).reshape(chan.shape[0], -1)

    def _hue_hist(self, rg, by, nbins=6, grid=4):
        """Per-region SATURATION-WEIGHTED HUE DISTRIBUTION. The opponent-colour axes are per-image normalized
        (natural images carry far more red-green than blue-yellow variance, so this balances the hue circle
        perceptually), then the angle atan2(by,rg) is soft-binned (von-Mises weights), saturation-weighted,
        pooled to a grid and per-cell normalized -- WHICH colours occur, in what proportion, per region,
        contrast/illumination-invariant. Captures material/scene colour composition. Per-image only."""
        rgn = rg / (rg.std(dim=(2, 3), keepdim=True) + 1e-6)
        byn = by / (by.std(dim=(2, 3), keepdim=True) + 1e-6)
        hue = torch.atan2(byn, rgn)
        sat = torch.sqrt(rgn ** 2 + byn ** 2 + 1e-6)
        g = (grid, grid) if isinstance(grid, int) else grid
        outs = []
        for k in range(nbins):
            center = -math.pi + (2 * math.pi) * (k + 0.5) / nbins
            w = torch.exp(9.0 * (torch.cos(hue - center) - 1.0))
            outs.append(F.adaptive_avg_pool2d(sat * w, g))
        h = torch.cat(outs, dim=1)
        h = h / (h.sum(1, keepdim=True) + 1e-6)
        return h.reshape(rg.shape[0], -1)

    def _sat_hist(self, rg, by, nbins=4, grid=4):
        """Per-region SATURATION (colorfulness) DISTRIBUTION. The opponent-colour magnitude is normalized by
        its per-image max and soft-binned into nbins levels, pooled to a grid and per-cell normalized -- how
        VIVID vs muted each region is (material/surface cue), orthogonal to hue identity and to luminance
        form. Per-image normalization only; never trained."""
        rgn = rg / (rg.std(dim=(2, 3), keepdim=True) + 1e-6)
        byn = by / (by.std(dim=(2, 3), keepdim=True) + 1e-6)
        sat = torch.sqrt(rgn ** 2 + byn ** 2 + 1e-6).sqrt()
        s = (sat / (sat.amax(dim=(2, 3), keepdim=True) + 1e-6)).clamp(0, 1)
        sigma = 0.5 / nbins
        outs = []
        for k in range(nbins):
            c = (k + 0.5) / nbins
            outs.append(F.adaptive_avg_pool2d(torch.exp(-((s - c) ** 2) / (2 * sigma ** 2)), (grid, grid)))
        h = torch.cat(outs, dim=1)
        h = h / (h.sum(1, keepdim=True) + 1e-6)
        return h.reshape(rg.shape[0], -1)

    def _light_hist(self, lum, nbins=5, grid=4):
        """Per-region LIGHTNESS (tonal) DISTRIBUTION. Luminance is per-image min-max normalized and soft-
        binned into nbins tonal levels, pooled to a grid and per-cell normalized -- the dark/mid/bright
        composition of each region (a scene/lighting cue: sky bright, foliage mid, indoor shadow), the
        tonal complement of the hue and saturation histograms, contrast-invariant. Per-image only."""
        lo = lum.amin(dim=(2, 3), keepdim=True); hi = lum.amax(dim=(2, 3), keepdim=True)
        l = ((lum - lo) / (hi - lo + 1e-6)).clamp(0, 1)
        sigma = 0.5 / nbins
        outs = []
        for k in range(nbins):
            c = (k + 0.5) / nbins
            outs.append(F.adaptive_avg_pool2d(torch.exp(-((l - c) ** 2) / (2 * sigma ** 2)), (grid, grid)))
        h = torch.cat(outs, dim=1)
        h = h / (h.sum(1, keepdim=True) + 1e-6)
        return h.reshape(lum.shape[0], -1)

    def _contrast_hist(self, lum, nbins=4, grid=4, k=5):
        """Per-region LOCAL-CONTRAST (texture-density) DISTRIBUTION. A local RMS-contrast map (sqrt of the
        kxk local variance) is per-image max-normalized and soft-binned, pooled to a grid and per-cell
        normalized -- how much of each region is SMOOTH (sky, walls, skin) vs TEXTURED (foliage, fabric,
        hair), as a distribution. A scene/material composition cue orthogonal to colour and to the mean
        oriented energy. Per-image normalization only; never trained."""
        mu = F.avg_pool2d(lum, k, stride=1, padding=k // 2)
        var = F.avg_pool2d(lum * lum, k, stride=1, padding=k // 2) - mu * mu
        c = (var.clamp_min(0) + 1e-6) ** 0.25
        c = c / (c.amax(dim=(2, 3), keepdim=True) + 1e-6)
        sigma = 0.5 / nbins
        outs = []
        for j in range(nbins):
            ctr = (j + 0.5) / nbins
            outs.append(F.adaptive_avg_pool2d(torch.exp(-((c - ctr) ** 2) / (2 * sigma ** 2)), (grid, grid)))
        h = torch.cat(outs, dim=1)
        h = h / (h.sum(1, keepdim=True) + 1e-6)
        return h.reshape(lum.shape[0], -1)

    def _chroma_contrast_hist(self, rg, by, nbins=4, grid=4, k=5):
        """Per-region CHROMA-CONTRAST (colourful-edge density) DISTRIBUTION. The local variance of the two
        opponent-colour channels is summed and rooted to a colour-variation map, per-image max-normalized
        and soft-binned, pooled and per-cell normalized -- how much COLOUR changes locally in each region
        (colourful textured boundaries vs flat colour fields), distinct from luminance contrast and from
        mean colour. A material/object cue. Per-image normalization only; never trained."""
        cc = 0.0
        for ch in (rg / (rg.std(dim=(2, 3), keepdim=True) + 1e-6),
                   by / (by.std(dim=(2, 3), keepdim=True) + 1e-6)):
            mu = F.avg_pool2d(ch, k, stride=1, padding=k // 2)
            var = F.avg_pool2d(ch * ch, k, stride=1, padding=k // 2) - mu * mu
            cc = cc + var.clamp_min(0)
        c = (cc + 1e-6) ** 0.25
        c = c / (c.amax(dim=(2, 3), keepdim=True) + 1e-6)
        sigma = 0.5 / nbins
        outs = []
        for j in range(nbins):
            ctr = (j + 0.5) / nbins
            outs.append(F.adaptive_avg_pool2d(torch.exp(-((c - ctr) ** 2) / (2 * sigma ** 2)), (grid, grid)))
        h = torch.cat(outs, dim=1)
        h = h / (h.sum(1, keepdim=True) + 1e-6)
        return h.reshape(rg.shape[0], -1)

    def _hue_light_hist(self, rg, by, lum, nhue=4, nlight=2, grid=2):
        """Per-region JOINT hue x lightness DISTRIBUTION -- a 2D colour-identity histogram (e.g. dark-green
        vs light-green, dark-red vs pink) that the marginal hue and lightness histograms cannot separate.
        Saturation-weighted soft bins in both dimensions, pooled to a grid and per-cell normalized over the
        joint bins. A richer material/surface colour cue; contrast/illumination-invariant, per-image only."""
        rgn = rg / (rg.std(dim=(2, 3), keepdim=True) + 1e-6)
        byn = by / (by.std(dim=(2, 3), keepdim=True) + 1e-6)
        hue = torch.atan2(byn, rgn)
        sat = torch.sqrt(rgn ** 2 + byn ** 2 + 1e-6)
        lo = lum.amin(dim=(2, 3), keepdim=True); hi = lum.amax(dim=(2, 3), keepdim=True)
        l = ((lum - lo) / (hi - lo + 1e-6)).clamp(0, 1)
        lsig = 0.5 / nlight
        outs = []
        for a in range(nhue):
            wh = torch.exp(9.0 * (torch.cos(hue - (-math.pi + 2 * math.pi * (a + 0.5) / nhue)) - 1.0))
            for b in range(nlight):
                wl = torch.exp(-((l - (b + 0.5) / nlight) ** 2) / (2 * lsig ** 2))
                outs.append(F.adaptive_avg_pool2d(sat * wh * wl, (grid, grid)))
        h = torch.cat(outs, dim=1).reshape(rg.shape[0], nhue * nlight, grid * grid)
        h = h / (h.sum(1, keepdim=True) + 1e-6)
        return h.reshape(rg.shape[0], -1)

    def _autocorr(self, e, lags, G):
        """Translation SELF-SIMILARITY (local autocorrelation) descriptor. For each spatial lag the
        oriented energy is correlated (per-orientation, per-cell) with a shifted copy of itself; the
        pattern of correlations across lags encodes texture PERIODICITY / regularity / repetition
        (buildings, tiles, foliage, fabric) -- a distinct relation from mirror symmetry (reflection) and
        from local Fourier (global periodicity), targeting scene/texture ventral (PPA/hV4)."""
        outs = []
        for (dy, dx) in lags:
            outs.append(self._local_corr(e, torch.roll(e, shifts=(dy, dx), dims=(2, 3)), G))
        return torch.cat(outs, dim=1)

    def _local_corr(self, a, b, G=2):
        """Per-orientation local correlation between two energy stacks on a grid (per-image). G is an int
        (square GxG) or an (h, w) tuple (rectangular, e.g. (3, 2) = vertical scene-layout bands)."""
        g = (G, G) if isinstance(G, int) else G
        ma = F.adaptive_avg_pool2d(a, g); mb = F.adaptive_avg_pool2d(b, g)
        mab = F.adaptive_avg_pool2d(a * b, g)
        va = F.adaptive_avg_pool2d(a * a, g) - ma * ma
        vb = F.adaptive_avg_pool2d(b * b, g) - mb * mb
        corr = ((mab - ma * mb) / (torch.sqrt(va.clamp_min(0) * vb.clamp_min(0)) + 1e-6)).clamp(-1, 1)
        return corr.reshape(corr.shape[0], -1)

    def _cross_gram(self, a, b, G=2):
        """Cross-scale Gram: full CxC correlation matrix between a fine and a coarse oriented-energy
        stack over a GxG grid -- every fine orientation vs every coarse orientation (diagonal = contour
        continuity, off-diagonal = corner/junction/curvature). Style/texture descriptor for ventral."""
        N, C, h, w = a.shape
        ma = F.adaptive_avg_pool2d(a, (G, G))
        mb = F.adaptive_avg_pool2d(b, (G, G))
        ab = torch.einsum('nihw,njhw->nijhw', a, b).reshape(N, C * C, h, w)
        p = F.adaptive_avg_pool2d(ab, (G, G)).reshape(N, C, C, G, G)
        cov = p - ma.unsqueeze(2) * mb.unsqueeze(1)
        va = (F.adaptive_avg_pool2d(a * a, (G, G)) - ma * ma).clamp_min(0)
        vb = (F.adaptive_avg_pool2d(b * b, (G, G)) - mb * mb).clamp_min(0)
        denom = torch.sqrt(va.unsqueeze(2) * vb.unsqueeze(1) + 1e-6)
        return (cov / denom).clamp(-1, 1).reshape(N, -1)

    def _logpolar_pool(self, energy):
        """Cortical-magnification pooling of an oriented-energy stack: resize to LP_SIZE and average
        within each log-ecc x angular region (per-image, foveally over-sampled retinotopy)."""
        e = F.adaptive_avg_pool2d(energy, (LP_SIZE, LP_SIZE))
        return torch.einsum('nchw,khw->nck', e, self._lp).reshape(energy.shape[0], -1)

    def _radial_freq(self, chan, gb, grid):
        """V4 radial-frequency / curvature descriptor at the given Gabor scale. Warp the image into
        LOG-POLAR coordinates (log radius x angle) via grid_sample, so CONCENTRIC rings become horizontal
        lines, RADIAL spokes become vertical lines, and spirals become obliques. A Gabor bank + DN energy
        in that warped space measures concentric/radial/spiral structure around fixation -- the radial-
        frequency (RF) pattern selectivity of V4/ventral shape cells and curved retinotopic contours --
        which the translation-oriented Cartesian energy backbone cannot represent."""
        N = chan.shape[0]
        g = self._lpwarp.expand(N, -1, -1, -1)
        warped = F.grid_sample(chan, g, mode="bilinear", padding_mode="border", align_corners=True)
        e = self._dn_full(_mag(warped, gb))
        return F.adaptive_avg_pool2d(e, grid).reshape(N, -1)

    def _dn_full(self, mag, block=5, sig=None):
        """Full-resolution V1 divisive-normalized oriented energy (contrast-invariant). Lower sig =
        the local energy pool dominates the denominator = stronger LOCAL contrast invariance."""
        if sig is None:
            sig = DN_SIG
        p = F.avg_pool2d((mag ** 2).sum(1, keepdim=True), block, stride=1, padding=block // 2)
        sigma2 = sig * (mag ** 2).mean(dim=(1, 2, 3), keepdim=True) + 1e-6
        return mag / torch.sqrt(sigma2 + p)

    def _dn_map(self, mag, block, grid):
        """V1 divisive-normalized retinotopic map, pooled to the retinotopic grid. Optionally a two-
        stage gain-control cascade (the cascade lifted early on the cross-scale Gram)."""
        dn = self._dn_cascade(mag, block) if DN_RETINO_STAGES == 2 else self._dn_full(mag, block)
        return F.adaptive_avg_pool2d(dn, (grid, grid)).reshape(mag.shape[0], -1)

    def _dn_cascade(self, mag, block=5):
        """Two-stage divisive-normalization cascade (successive gain-control stages up the hierarchy):
        stage 1 is the local cross-orientation DN; stage 2 re-normalizes that output by a BROADER
        spatial pool of its own energy, pushing the response further toward full contrast invariance."""
        r1 = self._dn_full(mag, block)
        b2 = 2 * block + 1
        p2 = F.avg_pool2d((r1 ** 2).sum(1, keepdim=True), b2, stride=1, padding=b2 // 2)
        sig2 = DN_SIG * (r1 ** 2).mean(dim=(1, 2, 3), keepdim=True) + 1e-6
        return r1 / torch.sqrt(sig2 + p2)

    def _dn_cov(self, mag, block=5):
        """Gain-controlled energy feeding the CO-OCCURRENCE descriptors (texture covariance, cross-scale
        Gram, cross-channel correlations). One or two DN stages via DN_COV_STAGES -- the co-occurrence
        readouts want maximal contrast invariance (scattering/retinotopy keep single-stage DN). The
        normalization neighbourhood is widened (DN_COV_BLOCK_MULT) since ventral RFs are larger, so the
        contrast invariance is pooled over a broader region than the retinotopic maps."""
        b = int(round(block * DN_COV_BLOCK_MULT)) | 1
        return self._dn_cascade(mag, b) if DN_COV_STAGES == 2 else self._dn_full(mag, b)

    def _global_fourier(self, chan, masks, size, win):
        x = F.adaptive_avg_pool2d(chan, (size, size)) * win
        amp = torch.fft.fftshift(torch.abs(torch.fft.fft2(x)), dim=(-2, -1)).squeeze(1)
        ampn = amp / (amp.sum(dim=(1, 2), keepdim=True) + 1e-8)
        binned = torch.einsum('nhw,khw->nk', ampn, masks)
        return torch.log1p(1000.0 * binned)

    def _windowed_fourier(self, chan, masks, cell, grid, win):
        """GIST-like spatial layout of spatial frequency: FFT the amplitude spectrum within each of a
        grid x grid tiling of the image, so WHERE each spatial-frequency/orientation lives is kept."""
        N = chan.shape[0]
        x = F.adaptive_avg_pool2d(chan, (cell * grid, cell * grid))
        p = x.unfold(2, cell, cell).unfold(3, cell, cell).reshape(-1, 1, cell, cell) * win
        amp = torch.fft.fftshift(torch.abs(torch.fft.fft2(p)), dim=(-2, -1)).squeeze(1)
        ampn = amp / (amp.sum(dim=(1, 2), keepdim=True) + 1e-8)
        binned = torch.log1p(1000.0 * torch.einsum('phw,khw->pk', ampn, masks))
        return binned.reshape(N, -1)

    def _local_contrast(self, chan, grids):
        """Local RMS contrast ('blur-variance'): per-cell standard deviation of the channel at several
        pooling grids -- an ISOTROPIC (orientation-agnostic) multiscale local-contrast / roughness map
        that complements the oriented energy and cues texture density / scene busyness (PPA/hV4)."""
        outs = []
        for g in grids:
            m = F.adaptive_avg_pool2d(chan, (g, g))
            m2 = F.adaptive_avg_pool2d(chan * chan, (g, g))
            outs.append((m2 - m * m).clamp_min(0).sqrt().reshape(chan.shape[0], -1))
        return torch.cat(outs, dim=1)

    def _marginals(self, x, grid):
        """Per-cell skewness and kurtosis of a scalar map -- bounded higher-order texture marginals
        (Portilla-Simoncelli style) that distinguish textures with matched mean and variance."""
        m1 = F.adaptive_avg_pool2d(x, (grid, grid))
        m2 = F.adaptive_avg_pool2d(x ** 2, (grid, grid))
        m3 = F.adaptive_avg_pool2d(x ** 3, (grid, grid))
        m4 = F.adaptive_avg_pool2d(x ** 4, (grid, grid))
        var = (m2 - m1 ** 2).clamp_min(1e-6)
        std = var.sqrt()
        skew = ((m3 - 3 * m1 * m2 + 2 * m1 ** 3) / (std ** 3 + 1e-6)).clamp(-6, 6)
        kurt = ((m4 - 4 * m1 * m3 + 6 * m1 ** 2 * m2 - 3 * m1 ** 4) / (var ** 2 + 1e-6)).clamp(0, 24)
        return torch.cat([skew, kurt], dim=1).reshape(x.shape[0], -1)

    def _curvature(self, chan, grid):
        """Contrast-normalized cornerness (Noble corner measure) from the structure tensor of the
        channel gradient: det(S)/trace(S) is high at corners / junctions / curved contours (V2/V4/
        ventral form) and, being a ratio of tensor invariants, is inherently contrast-normalized."""
        gx = F.conv2d(chan, self._sobel_x, padding=1)
        gy = F.conv2d(chan, self._sobel_y, padding=1)
        Sxx = F.avg_pool2d(gx * gx, 3, stride=1, padding=1)
        Syy = F.avg_pool2d(gy * gy, 3, stride=1, padding=1)
        Sxy = F.avg_pool2d(gx * gy, 3, stride=1, padding=1)
        corner = (Sxx * Syy - Sxy * Sxy) / (Sxx + Syy + 1e-6)
        return F.adaptive_avg_pool2d(corner, (grid, grid)).reshape(chan.shape[0], -1)

    def _hog(self, lum, nbins, grid):
        """Histogram of Oriented Gradients: soft-binned gradient-orientation histogram (magnitude-
        weighted) pooled to cells, then per-cell L2 block normalization -- a gradient-based, contrast-
        normalized orientation code distinct from the Gabor complex-cell energy. Bounded (unit-norm)."""
        gx = F.conv2d(lum, self._sobel_x, padding=1)
        gy = F.conv2d(lum, self._sobel_y, padding=1)
        mag = torch.sqrt(gx * gx + gy * gy + 1e-8)
        ang = torch.atan2(gy, gx) % math.pi
        bw = math.pi / nbins
        hs = []
        for b in range(nbins):
            center = (b + 0.5) * bw
            diff = torch.abs(ang - center)
            d = torch.minimum(diff, math.pi - diff)
            w = (1.0 - d / bw).clamp_min(0.0)
            hs.append(F.adaptive_avg_pool2d(mag * w, (grid, grid)))
        h = torch.cat(hs, dim=1)
        h = h / (h.pow(2).sum(1, keepdim=True).sqrt() + 1e-6)
        return h.reshape(lum.shape[0], -1)

    @torch.no_grad()
    def __call__(self, X):
        img = self._to_images(X)
        dev = img.device
        N = img.shape[0]
        if self._gb is None or self._gb.device != dev:
            self._gb = _gabor_bank(N_ORIENT, KSIZE, LAMBDA, SIGMA).to(dev)
            self._gbw = [_gabor_bank(N_ORIENT, k, lam, sig, gm).to(dev)
                         for (lam, sig, k), gm in zip(LUM_WLS, GRADED_GAMMA)]
            g = torch.Generator().manual_seed(RF_SEED)
            self._rf = (torch.randn(RF_CH, N_ORIENT, RF_K, RF_K, generator=g)
                        / math.sqrt(N_ORIENT * RF_K * RF_K)).to(dev)
            self._rf2 = (torch.randn(RF_CH, RF_CH, RF_K, RF_K, generator=g)
                         / math.sqrt(RF_CH * RF_K * RF_K)).to(dev)
            self._gb2 = _gabor_bank(N_ORIENT, KSIZE_B, LAMBDA_B, SIGMA_B).to(dev)
            self._s2 = _s2_bank().to(dev)
            self._dog = _dog_kernel().to(dev)
            self._iu = self._iu.to(dev)
            self._lp = self._lp.to(dev)
            self._lpwarp = self._lpwarp.to(dev)
            self._fmask = self._fmask.to(dev)
            self._fmask_c = self._fmask_c.to(dev)
            self._fmask_w = self._fmask_w.to(dev)
            self._win = self._win.to(dev)
            self._win_w = self._win_w.to(dev)
            self._sobel_x = self._sobel_x.to(dev)
            self._sobel_y = self._sobel_y.to(dev)
        r, g, b = img[:, 0], img[:, 1], img[:, 2]
        lum = (0.299 * r + 0.587 * g + 0.114 * b).unsqueeze(1)
        rg = (r - g).unsqueeze(1)
        by = (b - 0.5 * (r + g)).unsqueeze(1)

        feats = []
        lum_e_fine = None
        lum_es_fine = None
        lum_es_coarse = None
        lum_es_vcoarse = None
        # precompute all luminance oriented magnitudes (reused for retinotopic DN + contrast-invariant
        # texture energy)
        lum_mags = [_mag(lum, self._gbw[wi]) for wi in range(len(LUM_WLS))]
        # full-resolution multi-wavelength luminance energy (NO pyramid downsampling)
        for wi in range(len(LUM_WLS)):
            mag = lum_mags[wi]
            e = mag ** COMP_EXPS[wi]                      # per-scale graded compression, full 128px
            if wi == 1:
                lum_e_fine = e
            if wi == 2:
                lum_e_mid = e
            if wi == 3:
                lum_e_coarse = e
            gl = LUM_GRIDS[wi]
            feats.append(self._dn_map(mag, DN_BLOCKS[wi], gl))
            if wi in S2_LEVELS or wi in TEX_LEVELS:
                # RAW fourth-root energy feeds the conjunction net + second-order scattering (fine/mid
                # detail the EARLY stream uses); DIVISIVELY-NORMALIZED (contrast-invariant) energy feeds
                # the cross-orientation texture covariance only (the ventral co-occurrence descriptor).
                # Isolating whether the ventral gain rides on the texture-covariance DN, not the S2 DN.
                es_raw = F.adaptive_avg_pool2d(e, (STAT_SIZE, STAT_SIZE))
                es_dn = F.adaptive_avg_pool2d(self._dn_cov(mag, DN_BLOCKS[wi]), (STAT_SIZE, STAT_SIZE))
                if wi == 1:
                    lum_es_fine = es_raw
                if wi in S2_LEVELS:
                    s2 = self._second_order(es_raw)
                    feats.append(F.adaptive_avg_pool2d(s2, (S2_GRID, S2_GRID)).reshape(N, -1))
                # fine-scale texture covariance (wi=0,1) is ventral-load-bearing (no fine cross-scale Gram
                # subsumes it), so it is KEPT; a finest CONTRAST-INVARIANT PEAK (5x5) is added on top for V1
                if wi in TEX_LEVELS and wi not in (2, 3):
                    feats.append(self._texture_stats(es_dn))
                if wi == 0:
                    feats.append(F.adaptive_max_pool2d(self._dn_full(mag, DN_BLOCKS[0]), (5, 5)).reshape(N, -1))
        # CONTRAST-INVARIANT PEAK maps: max-pool of the divisively-normalized (gain-controlled) energy --
        # combines my two strongest levers (peak robustness + contrast invariance): the strongest gain-
        # controlled contour per cell. Fine (4x4) + mid (3x3) replace the coarse+mid texture covariance
        # (wi=2,3), which the cross-scale Gram (fine-vs-coarse/mid) already subsumes.
        feats.append(F.adaptive_max_pool2d(self._dn_full(lum_mags[1]), (4, 4)).reshape(N, -1))
        feats.append(F.adaptive_max_pool2d(self._dn_full(lum_mags[2]), (4, 4)).reshape(N, -1))
        feats.append(F.adaptive_max_pool2d(self._dn_full(lum_mags[3]), (2, 2)).reshape(N, -1))
        # contrast-invariant PEAK maps for the chromatic opponent channels (rg/by, fine wavelength) --
        # the strongest gain-controlled colour contour per cell (colour-form ventral)
        feats.append(F.adaptive_max_pool2d(self._dn_full(_mag(rg, self._gbw[1])), (2, 2)).reshape(N, -1))
        feats.append(F.adaptive_max_pool2d(self._dn_full(_mag(by, self._gbw[1])), (2, 2)).reshape(N, -1))
        # BILATERAL MIRROR-SYMMETRY descriptor (replaces the subsumed Cartesian log-polar pool): per-
        # orientation local correlation of the fine DN energy with its true left-right mirror (spatial
        # flip + orientation-channel reflection), pooled 3x3. High where structure is left-right symmetric
        # -- faces, centered objects -- a configural cue absent from every local energy statistic here.
        feats.append(self._symmetry(self._dn_full(lum_mags[1]), 3))
        # VERTICAL (up-down) symmetry of the fine energy -- the direct analog of the winning left-right
        # symmetry on the orthogonal axis (reflections, symmetric scene layout / horizons for PPA).
        # PHASE CONGRUENCY (contrast-invariant feature-point structure) replaces the whole-image vertical
        # (up-down) symmetry -- a low-value slot in prior swaps. Per orientation, the even/odd Gabor
        # responses summed across 3 scales, normalized by summed amplitude, mark true edges/lines
        # independent of contrast -- a signal ORTHOGONAL to the oriented ENERGY the rest of the model
        # already encodes exhaustively, targeting contour/form structure in ventral cortex.
        feats.append(self._phase_congruency(lum, [self._gbw[0], self._gbw[1], self._gbw[2], self._gbw[3]], 3))
        # TRANSLATION SELF-SIMILARITY (local autocorrelation): the fine energy correlated with shifted
        # copies of itself at H/V/diagonal lags gives texture periodicity/regularity, which lifted ventral
        # (PPA/hV4) strongly (new champion). Extend it: richer FINE lag set (near + far distances) + a MID
        # scale (coarser texture regularity), for multi-scale scene/texture structure. Funded by trimming
        # the fine Cartesian scattering grid (4->3).
        feats.append(self._autocorr(self._dn_full(lum_mags[1]),
                                    [(0, 3), (3, 0), (3, 3), (3, -3), (0, 6), (6, 0)], (3, 2)))
        feats.append(self._autocorr(self._dn_full(lum_mags[2]), [(0, 5), (5, 0), (5, 5)], 2))
        # CHROMA autocorrelation: translation self-similarity of the rg/by opponent fine energy -- colored
        # texture regularity (repeated colored patterns, foliage, fabric) for hV4/PPA colour-texture,
        # extending the winning self-similarity axis to the opponent-colour channels.
        for _cs in (rg, by):
            feats.append(self._autocorr(self._dn_full(_mag(_cs, self._gbw[1])), [(0, 5), (5, 0)], (3, 1)))
            feats.append(self._autocorr(self._dn_full(_mag(_cs, self._gbw[2])), [(0, 8), (8, 0)], (2, 1)))
        # V4 RADIAL-FREQUENCY / CURVATURE code at MULTIPLE scales: fine Gabor energy in log-polar-warped
        # image space lifted early (+0.0003, new champion); extend to mid + coarse scales, which detect
        # LARGER concentric/radial/spiral structure (big curved objects, radial scene layout / perspective)
        # -- rotational structure the translation-oriented Cartesian backbone provably cannot represent,
        # so non-redundant across scales. Fine/mid pooled 3(rings)x4(angles), coarse 2x4.
        feats.append(self._radial_freq(lum, self._gbw[1], (3, 4)))
        feats.append(self._radial_freq(lum, self._gbw[2], (3, 4)))
        feats.append(self._radial_freq(lum, self._gbw[3], (2, 4)))
        # CHROMA radial-frequency: the same log-polar-warped Gabor energy on the rg/by opponent channels
        # at the mid scale -- colored concentric/radial structure (round colored objects, fruit, faces),
        # extending the validated radial-frequency lever to colour-form, targeting hV4/ventral.
        feats.append(self._radial_freq(rg, self._gbw[2], (2, 4)))
        feats.append(self._radial_freq(by, self._gbw[2], (2, 4)))
        # RADIAL TEXTURE co-occurrence: cross-orientation correlations of the log-polar-warped fine energy
        # (per-cell std + pairwise correlations of the 8 orientation channels IN POLAR SPACE) -- captures
        # how radial vs angular vs oblique structure co-occur (a second-order polar texture statistic),
        # a V4/ventral shape-texture descriptor absent from the Cartesian texture Grams.
        _wg = self._lpwarp.expand(N, -1, -1, -1)
        _wlum = F.grid_sample(lum, _wg, mode="bilinear", padding_mode="border", align_corners=True)
        _we = F.adaptive_avg_pool2d(self._dn_full(_mag(_wlum, self._gbw[1])), (STAT_SIZE, STAT_SIZE))
        feats.append(self._texture_stats(_we))
        # ROTATIONAL (angular) SELF-SIMILARITY: autocorrelation of the log-polar-warped energy ALONG the
        # angle axis -- correlating with angular shifts of 90/120/180 degrees detects 4/3/2-fold ROTATIONAL
        # symmetry / radial periodicity (flowers, wheels, radial patterns, faces' 2-fold). Combines this
        # island's two winning axes (log-polar + self-similarity); a configural cue absent elsewhere.
        for _sh in (16, 21, 32):
            feats.append(self._local_corr(_we, torch.roll(_we, shifts=_sh, dims=3), 1))
        # local periodicity is now captured GLOBALLY by the Fourier power module below
        # DEEP random ReLU net (2 fixed random conv layers, RMS-normalized) on the fine energy --
        # hierarchical nonlinear conjunctions; combined here with the HOG block (previously tested apart)
        for src_es, gsz in ((lum_es_fine, RF_GRID),):
            rf = F.relu(F.conv2d(src_es, self._rf, padding=RF_K // 2))
            rf = rf / (rf.pow(2).mean(dim=(2, 3), keepdim=True).sqrt() + 1e-6)
            rf = F.relu(F.conv2d(rf, self._rf2, padding=RF_K // 2))
            rf = rf / (rf.pow(2).mean(dim=(2, 3), keepdim=True).sqrt() + 1e-6)
            feats.append(F.adaptive_avg_pool2d(rf, (gsz, gsz)).reshape(N, -1))
        # full-resolution chromatic energy at 2 wavelengths
        for chan in (rg, by):
            for ci, wi in enumerate(CHROMA_WL_IDX):
                magc = _mag(chan, self._gbw[wi])
                e = magc ** COMP_EXP
                gc = CHROMA_GRIDS[ci]
                feats.append(F.adaptive_avg_pool2d(e, (gc, gc)).reshape(N, -1))
                if ci == CHROMA_S2_LEVEL:
                    es = F.adaptive_avg_pool2d(e, (STAT_SIZE, STAT_SIZE))
                    s2c = self._second_order(es)
                    feats.append(F.adaptive_avg_pool2d(s2c, (CHROMA_S2_GRID, CHROMA_S2_GRID)).reshape(N, -1))
                    # contrast-invariant PEAK map for the mid chroma wavelength (strongest gain-controlled
                    # colour contour per cell) -- replaces the chroma texture covariance (invariant-peak
                    # beat texture covariance for luminance)
                    feats.append(F.adaptive_max_pool2d(self._dn_cov(magc), (3, 3)).reshape(N, -1))
        # foveal magnification: nested central crops processed at fine scale (FFA/VWFA foveal bias)
        for idx, (lo, hi, eg, sg) in enumerate(FOVEA_CROPS):
            fov = lum[:, :, lo:hi, lo:hi]
            magf = _mag(fov, self._gbw[0])
            ef = magf ** COMP_EXP
            feats.append(F.adaptive_avg_pool2d(ef, (eg, eg)).reshape(N, -1))
            # second foveal scale (mini-pyramid): coarser central form
            magf2 = _mag(F.avg_pool2d(fov, 2), self._gbw[0])
            ef2 = magf2 ** COMP_EXP
            feats.append(F.adaptive_avg_pool2d(ef2, (eg - 2, eg - 2)).reshape(N, -1))
            s2f = self._second_order(ef)
            feats.append(F.adaptive_avg_pool2d(s2f, (sg, sg)).reshape(N, -1))
            # foveal texture COVARIANCE on divisively-normalized (contrast-invariant) energy -- same
            # ventral lever, applied to the FFA/VWFA foveal co-occurrence descriptor (raw ef feeds the
            # retinotopic map + scattering above)
            # foveal contrast-invariant PEAK map (strongest gain-controlled central contour per cell) --
            # invariant-peak beat texture covariance elsewhere; targets foveal-biased FFA/VWFA
            feats.append(F.adaptive_max_pool2d(self._dn_cov(magf), (3, 3)).reshape(N, -1))
            # foveal DN-Gram (central-region contrast-invariant texture across the two foveal scales)
            # -- structured central form for FFA/VWFA, replacing the random foveal form filters
            if idx == 0:
                dn_ef = F.adaptive_avg_pool2d(self._dn_cov(magf), (STAT_SIZE // 2, STAT_SIZE // 2))
                dn_ef2 = F.adaptive_avg_pool2d(self._dn_cov(magf2), (STAT_SIZE // 2, STAT_SIZE // 2))
                feats.append(self._cross_gram(dn_ef, dn_ef2, 2))
        for chan in (lum, rg, by):
            p = F.adaptive_avg_pool2d(chan, (COLOR_GRID, COLOR_GRID))
            feats.append(p.reshape(p.shape[0], -1))
        # cross-channel luminance-color form correlations (scene color-form coupling for PPA), now on
        # divisively-normalized (contrast-invariant) energy -- same texture-covariance lever
        le, ce_rg, ce_by = (self._dn_cov(_mag(F.adaptive_avg_pool2d(c, (STAT_SIZE, STAT_SIZE)), self._gb))
                            for c in (lum, rg, by))
        feats.append(self._local_corr(le, ce_rg))
        feats.append(self._local_corr(le, ce_by))
        # --- GLOBAL Fourier structure ---
        # global amplitude spectrum (whole-image SF signature) dropped -- redundant with the oriented-
        # energy + log-polar features; its budget funds the fine/mid spatial chroma peak maps
        # windowed (GIST-like) spatial layout of spatial frequency -- scene SF layout (load-bearing)
        feats.append(self._windowed_fourier(lum, self._fmask_w, FFT_WIN_SIZE, FFT_WIN_GRID, self._win_w))
        # isotropic radial power of the two chromatic opponent channels (global color-SF distribution)
        for chan in (rg, by):
            feats.append(self._global_fourier(chan, self._fmask_c, FFT_SIZE, self._win))
        # HOG: block-normalized histogram of oriented GRADIENTS (8 bins, 3x3 cells) -- a gradient-based
        # contrast-normalized orientation code (a half-octave peak map here was neutral, so HOG kept)
        feats.append(self._hog(lum, 8, PC_GRID))
        # cross-scale GRAM on DIVISIVE-NORMALIZED energy: full fine-orientation x coarse-orientation
        # correlation matrices at two scale gaps, computed on contrast-invariant (DN) energy so the
        # texture co-occurrence generalizes like the DN retinotopic maps did
        # cross-scale GRAM on a TWO-STAGE DN cascade: fine-vs-coarse orientation correlation matrices
        # -- this early/mid-leaning descriptor benefited from the extra normalization stage (cleaner
        # early) whereas the ventral texture covariance kept single-stage DN
        # PER-REGION LIGHTNESS (tonal) DISTRIBUTION at object (4x4) and scene (2x2) scales -- the tonal
        # complement of the winning hue/saturation composition family -- replaces the fine-vs-coarse cross-
        # scale texture Gram (the colour-composition axis has beaten the texture-Gram axis on this reward).
        feats.append(self._light_hist(lum, 5, 4))
        feats.append(self._light_hist(lum, 5, 2))
        # PER-REGION HUE DISTRIBUTION (saturation-weighted, per-cell normalized) replaces the near-
        # duplicate fine-vs-vcoarse Gram: a contrast/illumination-invariant colour-composition descriptor
        # (material/scene colour) orthogonal to luminance form and to chroma energy -- targets PPA/ventral.
        # Enriched to 8 hue bins at a local (4x4) AND a global (2x2) scale (object- + scene-level colour).
        feats.append(self._hue_hist(rg, by, 8, 4))
        feats.append(self._hue_hist(rg, by, 8, 2))
        # SATURATION (colorfulness) composition -- how vivid vs muted each region is (material/surface cue,
        # orthogonal to hue identity) -- plus a FOVEAL hue histogram (central-object colour for FFA/objects,
        # e.g. skin/face hue). All contrast/illumination-invariant colour-composition signals.
        feats.append(self._sat_hist(rg, by, 4, 4))
        feats.append(self._hue_hist(rg[:, :, 32:96, 32:96], by[:, :, 32:96, 32:96], 8, 2))
        # CHROMA-CONTRAST (colourful-edge density) composition: how much colour varies locally per region
        # (colourful textured boundaries vs flat colour), orthogonal to luminance contrast -- replaces the
        # earlier neutral foveal-saturation/lightness additions (redundant with the global HSL histograms).
        feats.append(self._chroma_contrast_hist(rg, by, 4, 4))
        # LOCAL-CONTRAST (texture-density) composition: how much of each region is smooth vs textured, as a
        # per-cell distribution -- a scene/material cue orthogonal to colour, added in free budget.
        feats.append(self._contrast_hist(lum, 4, 4))
        feats.append(self._contrast_hist(lum, 4, 2))
        # MAX-pooled oriented energy (peak edge strength, not average) at the fine scale on a 6x6 grid --
        # captures sparse strong contours/textures that average pooling washes out (max-pooling was the
        # biggest historical gain); resolution raised 4x4 -> 6x6 using the freed mid-log-polar budget
        feats.append(F.adaptive_max_pool2d(lum_e_fine, (6, 6)).reshape(N, -1))
        # mid-scale peak (max) oriented energy on a 3x3 grid -- spatially-resolved peak contour strength
        # at the mid scale (V2/V3), extending the peak-energy lever across scales
        feats.append(F.adaptive_max_pool2d(lum_e_mid, (3, 3)).reshape(N, -1))
        # coarse-scale peak (max) oriented energy on a 2x2 grid -- spatially-resolved peak contour
        # strength at the coarse scale, replacing the now-redundant global (1x1) scale-max scalar
        feats.append(F.adaptive_max_pool2d(lum_e_coarse, (2, 2)).reshape(N, -1))
        # scale-invariant peak energy: element-wise MAX over the fine/mid/coarse oriented energy dropped
        # -- the spatially-resolved per-scale peak maps above subsume the global (1x1) scale-max
        # local RMS-contrast ('blur-variance'): isotropic multiscale local-contrast maps on luminance
        feats.append(self._local_contrast(lum, (5, 3)))
        # higher-order texture MARGINALS (skewness + kurtosis, Portilla-Simoncelli) of the contrast-
        # invariant fine DN energy (summed across orientations) on a 2x2 grid -- distinguishes textures
        # with matched mean/variance (sparse strong edges = high kurtosis); raised test, lowered train
        feats.append(self._marginals(self._dn_full(lum_mags[1]).sum(1, keepdim=True), 2))
        # chromatic peak (max) oriented energy: red-green/blue-yellow peak-contour strength. The fine
        # and mid wavelengths are now SPATIALLY-RESOLVED (2x2) like the luminance peak maps (extending
        # the per-scale peak lever to colour); the coarse wavelength stays whole-image (1x1)
        # chromatic peak (max) oriented energy: rg/by peak-contour strength; fine+mid wavelengths
        # spatially-resolved (2x2), coarse wavelength whole-image (1x1)
        feats.append(F.adaptive_max_pool2d(_mag(rg, self._gbw[1]) ** COMP_EXP, (2, 2)).reshape(N, -1))
        feats.append(F.adaptive_max_pool2d(_mag(by, self._gbw[1]) ** COMP_EXP, (2, 2)).reshape(N, -1))
        feats.append(F.adaptive_max_pool2d(_mag(rg, self._gbw[2]) ** COMP_EXP, (2, 2)).reshape(N, -1))
        feats.append(F.adaptive_max_pool2d(_mag(by, self._gbw[2]) ** COMP_EXP, (2, 2)).reshape(N, -1))
        # JOINT hue x lightness colour-identity histogram (dark vs light colours -- richer than marginal
        # hue+lightness) replaces the low-value global (1x1) coarse-chroma peak maxes.
        feats.append(self._hue_light_hist(rg, by, lum, 4, 2, 2))
        return torch.cat(feats, dim=1)


MODEL = Model()

